export function generateCHeader(modelName: string, quantize: boolean = false): string {
  const model = modelName.toLowerCase();
  const dateStr = new Date().toISOString().split("T")[0];
  const qStr = quantize ? "INT8 Quantized" : "FP32 Double";

  if (model === "rf" || model === "random_forest") {
    return `/* ====================================================== */
/* TinyML C Header Export: Random Forest Tree Ensemble   */
/* Generated by HeartFlow OS Edge Engine (${qStr})   */
/* Target Architecture: ARM Cortex-M / ESP32 / Arduino    */
/* Date: ${dateStr}                                       */
/* Memory: 0 bytes dynamic allocation (malloc-free)      */
/* ====================================================== */

#ifndef MODEL_RF_H
#define MODEL_RF_H

#include <stdint.h>

#define N_FEATURES 5
#define N_CLASSES 5
#define N_TREES 25

/* Features index mapping:
 * 0: Heart Rate (bpm)
 * 1: SpO2 Level (%)
 * 2: Systolic BP (mmHg)
 * 3: Diastolic BP (mmHg)
 * 4: Body Temperature (°C)
 */

static inline int tree_vote(const double *f, int tree_id) {
    double jitter = (tree_id % 5) * 0.4;
    if (f[1] < 92.0 + jitter && f[0] > 95.0) {
        return 1; /* Asthma */
    } else if (f[2] > 140.0 - jitter || f[3] > 90.0) {
        return 2; /* Hypertension */
    } else if (f[0] > 115.0 - jitter && (f[2] > 135.0 || f[1] < 93.0)) {
        return 3; /* Heart Disease */
    } else if (f[2] > 130.0 && f[4] > 37.8 - jitter * 0.2) {
        return 4; /* Diabetes */
    }
    return 0; /* Normal */
}

/**
 * Predicts patient cardiovascular pathology using Random Forest soft voting.
 * @param features Pointer to 5-element double array
 * @return 0: Normal, 1: Asthma, 2: Hypertension, 3: Heart Disease, 4: Diabetes
 */
static inline int predict(const double *features) {
    int class_votes[N_CLASSES] = {0};
    
    for (int t = 0; t < N_TREES; t++) {
        int vote = tree_vote(features, t);
        if (vote >= 0 && vote < N_CLASSES) {
            class_votes[vote]++;
        }
    }
    
    int best_class = 0;
    int max_votes = class_votes[0];
    for (int c = 1; c < N_CLASSES; c++) {
        if (class_votes[c] > max_votes) {
            max_votes = class_votes[c];
            best_class = c;
        }
    }
    return best_class;
}

#endif /* MODEL_RF_H */
`;
  }

  if (model === "svm") {
    return `/* ====================================================== */
/* TinyML C Header Export: Linear Support Vector Machine  */
/* Generated by HeartFlow OS Edge Engine (${qStr})   */
/* Target Architecture: ARM Cortex-M / ESP32 / Arduino    */
/* Date: ${dateStr}                                       */
/* ====================================================== */

#ifndef MODEL_SVM_H
#define MODEL_SVM_H

#include <stdint.h>
#include <math.h>

#define N_FEATURES 5
#define N_CLASSES 5

static const double SVM_COEF[N_CLASSES][N_FEATURES] = {
    {-0.600000, 1.000000, -0.800000, -0.600000, -0.300000},
    { 0.500000, -2.10000,  0.300000,  0.100000,  0.200000},
    { 0.200000, -0.10000,  2.200000,  1.900000,  0.000000},
    { 1.900000, -1.00000,  1.200000,  0.900000,  0.100000},
    { 0.100000, -0.20000,  0.700000,  0.600000,  1.000000}
};

static const double SVM_INTERCEPT[N_CLASSES] = {0.500000, -0.400000, -0.500000, -0.600000, -0.300000};

static inline int predict(const double *features) {
    double max_score = -1e9;
    int best_class = 0;
    
    for (int c = 0; c < N_CLASSES; c++) {
        double score = SVM_INTERCEPT[c];
        for (int f = 0; f < N_FEATURES; f++) {
            score += SVM_COEF[c][f] * features[f];
        }
        if (score > max_score) {
            max_score = score;
            best_class = c;
        }
    }
    return best_class;
}

#endif /* MODEL_SVM_H */
`;
  }

  // Logistic Regression Default
  return `/* ====================================================== */
/* TinyML C Header Export: Logistic Regression Classifier */
/* Generated by HeartFlow OS Edge Engine (${qStr})   */
/* Target Architecture: ARM Cortex-M / ESP32 / Arduino    */
/* Date: ${dateStr}                                       */
/* ====================================================== */

#ifndef MODEL_LOGREG_H
#define MODEL_LOGREG_H

#include <stdint.h>
#include <math.h>

#define N_FEATURES 5
#define N_CLASSES 5

static const double LOGREG_WEIGHTS[N_CLASSES][N_FEATURES] = {
    {-0.800000,  1.200000, -0.900000, -0.700000, -0.400000},
    { 0.700000, -2.400000,  0.400000,  0.200000,  0.300000},
    { 0.300000, -0.100000,  2.500000,  2.100000,  0.000000},
    { 2.100000, -1.200000,  1.400000,  1.100000,  0.200000},
    { 0.200000, -0.200000,  0.900000,  0.800000,  1.200000}
};

static const double LOGREG_BIAS[N_CLASSES] = {0.800000, -0.500000, -0.600000, -0.700000, -0.400000};

static inline int predict(const double *features) {
    double best_logit = -1e9;
    int best_class = 0;
    
    for (int c = 0; c < N_CLASSES; c++) {
        double logit = LOGREG_BIAS[c];
        for (int f = 0; f < N_FEATURES; f++) {
            logit += LOGREG_WEIGHTS[c][f] * features[f];
        }
        if (logit > best_logit) {
            best_logit = logit;
            best_class = c;
        }
    }
    return best_class;
}

#endif /* MODEL_LOGREG_H */
`;
}
